/bin/zsh -lc "python3 - <<'PY'
from pathlib import Path
import os, tempfile
p = Path('main.go')
content = '''package main

import (
	\"crypto/rand\"
	\"html/template\"
	\"log\"
	\"math/big\"
	\"os\"
)

func main() {
	n, err := rand.Int(rand.Reader, big.NewInt(1_000_000))
	if err "'!= nil {
		log.Fatal(err)
	}

	tmpl, err := template.New("greeting").Parse("Hello World {{.}}'"\\\\n\")
	if err "'!= nil {
		log.Fatal(err)
	}
	if err := tmpl.Execute(os.Stdout, n); err != nil {
		log.Fatal(err)
	}
}
'"'''
fd, tmp = tempfile.mkstemp(dir='.', prefix='.main.go.')
try:
    with os.fdopen(fd, 'w') as f:
        f.write(content)
        f.flush()
        os.fsync(f.fileno())
    os.replace(tmp, p)
finally:
    if os.path.exists(tmp):
        os.unlink(tmp)
PY
gofmt -w main.go
